(()=>{'use strict';
 const $=s=>document.querySelector(s),isManager=()=>typeof mine==='function'&&['director','supervisor'].includes(mine()?.role),q=s=>document.querySelector(s);
 const eligible=()=>members.filter(m=>m.active&&!m.external&&(mine().role==='director'||m.role!=='director'));
 const optionList=(selected,review=false)=>`<option value="">${review?'بدون نیاز به تأیید':'انتخاب مسئول'}</option>`+eligible().filter(m=>!review||['director','supervisor'].includes(m.role)).map(m=>`<option value="${m.id}" ${m.id===selected?'selected':''}>${esc(m.name)}</option>`).join('');
 function inject(){const toolbar=q('.routine-reminders .routine-toolbar');if(!toolbar||!isManager()||q('#workflowTemplatesOpen'))return;const b=document.createElement('button');b.type='button';b.id='workflowTemplatesOpen';b.className='secondary workflow-open';b.textContent='قالب مراحل کار';b.title='تعریف فرآیندهای مرحله‌ای بدون زمان‌بندی تکراری';b.onclick=open;toolbar.prepend(b)}
 async function list(){return await rpc('sm_workflow_list',{p_project:project.id})}
 function home(rows=[]){return modalHead('قالب مراحل کار')+`<section class="workflow-templates"><p class="workflow-intro">برای کارهای چندمرحله‌ای استفاده کنید. همهٔ مسئولان هنگام آغاز فرآیند در جریان قرار می‌گیرند؛ اما هر مرحله فقط پس از پایان مرحلهٔ قبل فعال می‌شود و مهلتش از همان زمان محاسبه خواهد شد.</p><div class="workflow-toolbar"><button class="secondary" type="button" id="workflowBack">بازگشت به کارهای روتین</button><button class="primary" type="button" id="workflowNew">＋ قالب جدید</button></div><div id="workflowList">${rows.length?rows.map(r=>`<article class="workflow-template"><div><strong>${esc(r.title)}</strong>${r.description?`<p>${esc(r.description)}</p>`:''}<small>${fa(r.steps.length)} مرحله · ${r.steps.map(s=>esc(s.title)).join(' ← ')}</small></div><button type="button" class="primary" data-workflow-start="${r.id}">شروع فرآیند</button></article>`).join(''):'<div class="workflow-empty">هنوز قالب مرحله‌ای ندارید. یک قالب بسازید تا هر زمان لازم شد با یک کلیک آغازش کنید.</div>'}</div></section>`}
 async function open(){if(!isManager())return;modal(modalHead('قالب مراحل کار')+'<section class="workflow-templates"><div class="workflow-loading">در حال دریافت قالب‌ها…</div></section>');try{const rows=await list();$('#sharedDetail').innerHTML=home(rows);bindHome(rows)}catch(e){message(failure(e))}}
 function bindHome(rows){$('#workflowBack').onclick=()=>window.SamandisOpenRoutines?.();$('#workflowNew').onclick=()=>editor();document.querySelectorAll('[data-workflow-start]').forEach(b=>b.onclick=async()=>{const row=rows.find(r=>r.id===b.dataset.workflowStart);if(!row||!confirm(`فرآیند «${row.title}» شروع شود؟ همه مسئولان از ابتدا در جریان قرار می‌گیرند.`))return;b.disabled=true;try{await rpc('sm_workflow_activate',{p_template:row.id});await refresh();message('فرآیند آغاز شد و مراحل طبق ترتیب فعال می‌شوند.')}catch(e){b.disabled=false;message(failure(e))}})}
 function step(data={},number=1){return `<article class="workflow-step" data-workflow-step><header><b>مرحلهٔ ${fa(number)}</b><button type="button" class="text-btn" data-remove-step>حذف</button></header><label>عنوان مرحله<input name="step_title" required maxlength="160" value="${esc(data.title||'')}"></label><label>مسئول انجام<select name="step_owner" required>${optionList(data.owner_id)}</select></label><label>تأییدکننده<select name="step_reviewer">${optionList(data.reviewer_id,true)}</select></label><label>مهلت پس از پایان مرحلهٔ قبل<input name="step_days" required type="number" min="1" max="365" value="${data.duration_days||1}"><small>روز</small></label><label>شرح مرحله <small>(اختیاری)</small><textarea name="step_description" rows="2" maxlength="4000">${esc(data.description||'')}</textarea></label></article>`}
 function editor(){const owner=eligible()[0]?.id||'';modal(modalHead('قالب مراحل جدید')+'<section class="workflow-editor"><p>مهلت مرحلهٔ اول از روز آغاز فرآیند محاسبه می‌شود؛ مهلت هر مرحلهٔ بعدی از پایان مرحلهٔ قبل.</p><form id="workflowForm"><label>عنوان فرآیند<input name="title" required maxlength="160" placeholder="مثلاً ارسال صورت‌وضعیت ماهانه"></label><label>شرح کلی <small>(اختیاری)</small><textarea name="description" rows="3" maxlength="2000"></textarea></label><div id="workflowSteps">'+step({owner_id:owner},1)+'</div><button class="secondary" type="button" id="workflowAddStep">＋ افزودن مرحله</button><div class="workflow-form-actions"><button class="primary" type="submit">ذخیره قالب</button></div></form></section>');const f=$('#workflowForm'),box=$('#workflowSteps');const wire=()=>{box.querySelectorAll('[data-remove-step]').forEach(b=>b.onclick=()=>{if(box.children.length===1)return message('حداقل یک مرحله لازم است.');b.closest('[data-workflow-step]').remove();renumber()})},renumber=()=>{[...box.children].forEach((x,i)=>x.querySelector('header b').textContent='مرحلهٔ '+fa(i+1));wire()};wire();$('#workflowAddStep').onclick=()=>{box.insertAdjacentHTML('beforeend',step({owner_id:owner},box.children.length+1));wire()};f.onsubmit=async e=>{e.preventDefault();const submit=f.querySelector('[type=submit]'),steps=[...box.querySelectorAll('[data-workflow-step]')].map((node,i)=>({sequence:i+1,title:node.querySelector('[name=step_title]').value.trim(),owner_id:node.querySelector('[name=step_owner]').value,reviewer_id:node.querySelector('[name=step_reviewer]').value||null,duration_days:Number(node.querySelector('[name=step_days]').value),description:node.querySelector('[name=step_description]').value.trim()}));if(steps.some(s=>!s.title||!s.owner_id||!s.duration_days))return message('مشخصات همهٔ مراحل را کامل کنید.');submit.disabled=true;try{await rpc('sm_workflow_save',{p_project:project.id,p_id:null,p_title:f.title.value.trim(),p_description:f.description.value.trim(),p_steps:steps});message('قالب مراحل ذخیره شد.');open()}catch(e){submit.disabled=false;message(failure(e))}}}
 function decorate(){document.querySelectorAll('#sharedContent [data-task],#sharedContent [data-shared-card]').forEach(node=>{const t=tasks.find(x=>x.id===(node.dataset.task||node.dataset.sharedCard));const old=node.querySelector('.workflow-blocked');if(!t||!t.description.includes('این مرحله پس از پایان مرحلهٔ قبل فعال می‌شود.')||t.due){old?.remove();return}if(old)return;const badge=document.createElement('small');badge.className='workflow-blocked';badge.textContent='در انتظار مرحلهٔ قبل';node.append(badge);document.querySelector(`[data-complete="${CSS.escape(t.id)}"]`)?.setAttribute('disabled','')})}
 const oldRender=render;render=function(...args){const v=oldRender(...args);queueMicrotask(decorate);return v};const oldTasks=renderTasks;renderTasks=function(...args){const v=oldTasks(...args);queueMicrotask(decorate);return v};new MutationObserver(inject).observe(document.body,{childList:true,subtree:true});inject();decorate();
})();
